336	static int bk7258_rptun_notify(struct rptun_dev_s *dev, uint32_t vqid)
337	{
338	  struct bk7258_rptun_dev_s *priv =
339	    container_of(dev, struct bk7258_rptun_dev_s, rptun);
340	  int peer = priv->master ? 1 : 0;
341	  irqstate_t flags;
342	  int ret;
343	
344	  (void)vqid;
345	  bk7258_rptun_barrier();
346	  /* Every Mailbox entry is an idempotent request to scan all virtqueues.
347	   * Keep at most one doorbell outstanding in each direction.  This explicit
348	   * latch, rather than the instantaneous FIFO-full state, makes coalescing
349	   * race-free: the receiver clears it before scanning the virtqueues.
350	   */
351	
352	  flags = enter_critical_section();
353	  if (priv->shmem->mbox_pending[peer] != 0)
354	    {
355	      leave_critical_section(flags);
356	      return 0;
357	    }
358	
359	  priv->shmem->mbox_pending[peer] = 1;
360	  bk7258_rptun_barrier();
361	
362	  /* A doorbell that returns -EBUSY means the peer FIFO was momentarily full
363	   * (the peer had not yet drained a previous kick).  Losing this kick would
364	   * leave data in the vring with no scan and deadlock the uart_rpmsg ACK
365	   * round-trip, so spin-retry while holding the latch until the kick lands. */
366	
367	  ret = bk7258_mbox_notify(peer, RPTUN_NOTIFY_ALL);
368	  while (ret == -EBUSY)
369	    {
370	      volatile unsigned int spin;
371	
372	      for (spin = 0; spin < 200; spin++)
373	        {
374	          __asm__ volatile ("nop");
375	        }
376	
377	      ret = bk7258_mbox_notify(peer, RPTUN_NOTIFY_ALL);
378	    }
